<?php namespace Workspace; ?>
<section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="search"><label>Поиск<input type="search" name="q" maxlength="120" value="<?= h($term) ?>" required></label><label>Проект<select name="project"><?php selectOptions([''=>'Все доступные']+$projects,$project??'') ?></select></label><label>Тип объекта<select name="kind"><?php selectOptions($labels,$kind) ?></select></label><button class="primary">Найти</button></form><p class="muted">Поиск по названиям, реквизитам и разрешённым полям. Forum проверяется в выбранном проекте; без проекта доступен только локальный поиск.</p></section>
<?php if($restricted): ?><p class="notice">Для источников с усиленной защитой подтвердите <a href="<?= h(url('security')) ?>">второй фактор</a>.</p><?php endif ?>
<?php foreach($errors as $k=>$message): ?><p class="notice"><?= h($labels[$k].': '.$message) ?></p><?php endforeach ?>
<?php foreach($matches as $k=>$rows): ?><section class="panel"><div class="panelhead"><h2><?= h($labels[$k]) ?></h2><span class="count"><?= count($rows) ?></span></div><?php if(!$rows): ?><p class="empty">Ничего не найдено.</p><?php endif ?><?php foreach($rows as $r): ?><div class="splitrow"><a href="<?= h($k==='forum'?url('forum',['project'=>$r['project_id'],'source'=>$r['source_id'],'topic'=>$r['id']]):discoveryHref($r,$k)) ?>"><?= h($r['title']) ?></a><span class="muted"><?= h($r['project_title']??$projects[$r['project_id']]??'') ?></span></div><?php endforeach ?><?php if(($more[$k]??false)||($k==='forum'&&$rows)): ?><p><a href="<?= h(url('search',['q'=>$term,'project'=>$project??'','kind'=>$k,'n'=>$kind===$k?$pageNo+1:1])) ?>"><?= $kind===$k?'Следующая страница':'Все результаты типа' ?></a></p><?php endif ?><?php if($kind===$k&&$pageNo>1): ?><p><a href="<?= h(url('search',['q'=>$term,'project'=>$project??'','kind'=>$k,'n'=>$pageNo-1])) ?>">Предыдущая страница</a></p><?php endif ?></section><?php endforeach ?>
